#include <stdio.h>

/* teste do desafio tabela-de-comparacoes — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   A captura do stdout acontece DENTRO do teste (modelo cenario-do-harness):
   freopen manda o stdout para o arquivo temporario, o teste chama a funcao
   do aluno e le o arquivo de volta — stdlib puro, sem runner proprio. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void tabelaDeComparacoes(void);

SM_TEST(a_tabela_das_cinco_comparacoes) {
    /* captura: o stdout vira o arquivo sm_saida.tmp */
    freopen("sm_saida.tmp", "w", stdout);
    tabelaDeComparacoes();
    fflush(stdout);

    /* leitura linha a linha: uma comparacao por linha, na ordem do arquivo */
    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a linha do 4 == 4", linha, "4 == 4 -> 1\n",
              "os dois lados sao iguais, entao o == devolve 1");
    fgets(linha, 80, f);
    checa_str("a linha do 4 == 5", linha, "4 == 5 -> 0\n",
              "quatro nao e cinco, entao o == devolve 0");
    fgets(linha, 80, f);
    checa_str("a linha do 7 >= 7", linha, "7 >= 7 -> 1\n",
              "o >= aceita o igual: sete e maior ou igual a sete");
    fgets(linha, 80, f);
    checa_str("a linha do 9 >= 7", linha, "9 >= 7 -> 1\n",
              "nove e maior que sete, entao o >= devolve 1");
    fgets(linha, 80, f);
    checa_str("a linha do 5 >= 9", linha, "5 >= 9 -> 0\n",
              "cinco nao e maior nem igual a nove, entao o >= devolve 0");
    /* a saida TERMINA na quinta linha — buffer novo com sentinel */
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "sao cinco comparacoes: nenhuma sexta linha e aceita");
    fclose(f);
}

