#include <stdio.h>

void tabelaDeComparacoes(void) {
    printf("4 == 4 -> %d\n", 4 == 4);
    printf("4 == 5 -> %d\n", 4 == 5);
    printf("7 >= 7 -> %d\n", 7 >= 7);
    printf("9 >= 7 -> %d\n", 9 >= 7);
    printf("5 >= 9 -> %d\n", 5 >= 9);
}
